// Choose the AI provider. Default below; switch per message with /claude, /deepseek or /gemini.
const DEFAULT_PROVIDER = 'deepseek';
const NAMES = { claude: 'Claude', deepseek: 'DeepSeek', gemini: 'Gemini' };
const j = $input.first().json;
let text = String(j.chatInput || '').trim();
let provider = DEFAULT_PROVIDER;
const m = text.match(/^\/(claude|deepseek|gemini)\b\s*/i);
if (m) { provider = m[1].toLowerCase(); text = text.slice(m[0].length) || 'hi'; }
return [{ json: { sessionId: j.sessionId, chatInput: text, provider, provider_name: NAMES[provider] } }];

