{
  "type": "object",
  "properties": {
    "intent": {
      "type": "string",
      "description": "One of: book (wants an appointment or gives booking details), confirm (agrees: yes, ok, sounds good), deny (says no to the proposed booking or wants to change), question (asks about hours, prices, services, location), greeting, other"
    },
    "service": {
      "type": [
        "string",
        "null"
      ],
      "description": "One of: checkup (check-up, cleaning, scale and polish), whitening (teeth whitening, bleaching), emergency (pain, broken tooth, swelling, urgent). Null if not mentioned."
    },
    "date": {
      "type": [
        "string",
        "null"
      ],
      "description": "Requested day as YYYY-MM-DD, resolving words like tomorrow, next Tuesday, Friday, the 20th using today's date. Null if not mentioned."
    },
    "time_of_day": {
      "type": [
        "string",
        "null"
      ],
      "description": "morning, afternoon or evening if mentioned, else null"
    },
    "exact_time": {
      "type": [
        "string",
        "null"
      ],
      "description": "Requested clock time as HH:mm in 24h format (e.g. 2pm = 14:00). Null if not mentioned."
    },
    "option_number": {
      "type": [
        "integer",
        "null"
      ],
      "description": "If the patient picks one of the numbered options (e.g. 'the second one', '3'), its number. Else null."
    },
    "name": {
      "type": [
        "string",
        "null"
      ],
      "description": "Patient full name if given, else null"
    },
    "phone": {
      "type": [
        "string",
        "null"
      ],
      "description": "Phone number if given, else null"
    }
  },
  "required": [
    "intent"
  ]
}

