// Booking logic: the AI only UNDERSTANDS the message; this code decides slots, so the bot can never double-book.
const CLINIC = { name: 'Smile Dental Clinic', tz: 'America/Chicago', tzLabel: 'Central Time', hours: [9, 10, 11, 13, 14, 15, 16], searchDays: 10,
  info: 'Smile Dental Clinic is open Monday to Friday, 9 AM to 5 PM Central Time (lunch 12-1 PM).' };
const SERVICES = { checkup: { label: 'Check-up & cleaning', minutes: 45, price: 120 }, whitening: { label: 'Teeth whitening', minutes: 60, price: 350 }, emergency: { label: 'Emergency visit', minutes: 30, price: 90 } };
const menu = () => Object.values(SERVICES).map((s, i) => `${i + 1}. ${s.label} (${s.minutes} min, from $${s.price})`).join('\n');

const p = $('Pick AI Provider').first().json;
const sessionId = p.sessionId;
const ai = ($('Understand Message').first().json.output) || {};
const row = $('Load Session').all().map(i => i.json).find(r => r.sessionId === sessionId);
let s = row && row.state ? JSON.parse(row.state) : { step: 'collect' };
const booked = new Set($('Load Booked Slots').all().map(i => i.json).filter(r => r.status === 'booked' && r.start_iso).map(r => r.start_iso));
const now = DateTime.now().setZone(CLINIC.tz);
const clean = v => (v === null || v === undefined || v === '' || v === 'null') ? null : v;

// --- free slots matching the patient's preference ---
function slots({ date, tod, time }, limit) {
  const out = [];
  let day = date ? DateTime.fromISO(date, { zone: CLINIC.tz }).startOf('day') : now.startOf('day').plus({ days: 1 });
  if (day < now.startOf('day')) day = now.startOf('day');
  for (let d = 0; d < CLINIC.searchDays && out.length < limit; d++, day = day.plus({ days: 1 })) {
    if (day.weekday > 5) continue;
    let hours = CLINIC.hours;
    if (tod === 'morning') hours = hours.filter(h => h < 12);
    if (tod === 'afternoon' || tod === 'evening') hours = hours.filter(h => h >= 13);
    if (time) { const h = parseInt(time, 10); hours = [...hours].sort((a, b) => Math.abs(a - h) - Math.abs(b - h)); }
    for (const h of hours) {
      const t = day.set({ hour: h, minute: 0, second: 0, millisecond: 0 });
      if (t <= now.plus({ hours: 2 })) continue;
      const iso = t.toUTC().toISO();
      if (!booked.has(iso)) out.push({ iso, label: t.toFormat('ccc d LLL, h:mm a') });
      if (out.length >= limit) break;
    }
  }
  return out;
}

// --- merge what the AI understood ---
const intent = clean(ai.intent) || 'other';
if (s.step === 'done' && intent === 'book') s = { step: 'collect', name: s.name, phone: s.phone };
for (const k of ['service', 'date', 'time_of_day', 'exact_time', 'name', 'phone']) {
  const v = clean(ai[k]);
  if (v !== null) {
    const key = k === 'time_of_day' ? 'tod' : k === 'exact_time' ? 'time' : k;
    if (['date', 'tod', 'time'].includes(key) && s[key] !== v) { s.slot = null; s.offered = null; if (s.step === 'confirm') s.step = 'collect'; }
    s[key] = v;
  }
}
// a new part-of-day without a new exact time replaces the old exact time
if (clean(ai.time_of_day) !== null && clean(ai.exact_time) === null) s.time = null;
const askedExact = clean(ai.exact_time) !== null;
const askedDate = clean(ai.date) !== null;
if (s.phone) { const d = String(s.phone).replace(/\D/g, ''); s.phone = d.length >= 9 ? '+' + (d.length === 10 ? '1' + d : d) : null; }
if (s.service && !SERVICES[s.service]) s.service = null;

let reply = '';
let booking = null;

if (intent === 'question' && s.step !== 'confirm') {
  reply = CLINIC.info + '\nServices:\n' + menu() + '\n\nWould you like to book a visit? Just tell me what and when, e.g. "a cleaning next Tuesday afternoon".';
} else if (s.step === 'done') {
  reply = `Your ${SERVICES[s.service].label} is booked for ${s.slot.label} (${CLINIC.tzLabel}). Say "book another" to make a new appointment, or call us to change it.`;
} else if (s.step === 'confirm' && intent === 'confirm') {
  if (booked.has(s.slot.iso)) { s.slot = null; s.step = 'collect'; reply = 'Sorry, that time was just taken. '; }
  else {
    booking = { sessionId, patient_name: s.name, phone: s.phone, service: SERVICES[s.service].label, start_iso: s.slot.iso, start_label: s.slot.label, status: 'booked', reminded: false };
    s.step = 'done';
    reply = `You're booked! ${SERVICES[s.service].label} on ${s.slot.label} (${CLINIC.tzLabel}). We'll send a reminder 24 hours before. See you soon, ${String(s.name).split(' ')[0]}!`;
  }
} else if (s.step === 'confirm' && intent === 'deny') {
  s.slot = null; s.offered = null; s.step = 'collect';
  reply = 'No problem. What day or time would suit you better?';
}

if (!reply) {
  // pick from offered list ("the second one", "2", "10am works")
  const opt = parseInt(clean(ai.option_number), 10);
  if (!s.slot && s.offered && opt >= 1 && opt <= s.offered.length) s.slot = s.offered[opt - 1];
  if (!s.slot && s.offered && s.time) { const hit = s.offered.find(o => DateTime.fromISO(o.iso).setZone(CLINIC.tz).hour === parseInt(s.time, 10) && (!s.date || DateTime.fromISO(o.iso).setZone(CLINIC.tz).toISODate() === s.date)); if (hit) s.slot = hit; }
  if (s.slot && booked.has(s.slot.iso)) s.slot = null;

  if (!s.service) {
    reply = (intent === 'greeting' || !s.date ? `Hi! I'm the booking assistant for ${CLINIC.name}. ` : '') + 'What would you like to book?\n' + menu();
  } else if (!s.slot) {
    const want = { date: s.date, tod: s.tod, time: s.time };
    const list = slots(want, 4);
    const exact = s.time && s.date && list.find(o => { const t = DateTime.fromISO(o.iso).setZone(CLINIC.tz); return t.toISODate() === s.date && t.hour === parseInt(s.time, 10); });
    if (exact) { s.slot = exact; }
    else if (!list.length) { reply = 'Sorry, nothing is free around then. Could you suggest another day?'; }
    else {
      s.offered = list;
      const asked = s.date ? DateTime.fromISO(s.date, { zone: CLINIC.tz }).toFormat('cccc d LLL') : null;
      const sameDay = asked && list.some(o => DateTime.fromISO(o.iso).setZone(CLINIC.tz).toISODate() === s.date);
      reply = ((askedExact && s.time) ? 'That exact time is not available. ' : (askedDate && asked && !sameDay) ? 'Nothing is free on ' + asked + '. ' : '') + `Here are the closest free times for ${SERVICES[s.service].label} (${CLINIC.tzLabel}):\n` + list.map((o, i) => `${i + 1}. ${o.label}`).join('\n') + '\n\nWhich one works for you?';
    }
  }
  if (!reply && s.slot) {
    if (!s.name) reply = `${s.slot.label} is free. May I have your full name?`;
    else if (!s.phone) reply = `Thanks, ${String(s.name).split(' ')[0]}. What's the best phone number for your reminder?`;
    else { s.step = 'confirm'; reply = `Please confirm:\n- ${SERVICES[s.service].label}\n- ${s.slot.label} (${CLINIC.tzLabel})\n- ${s.name}, ${s.phone}\n\nShall I book it?`; }
  }
}

s.last_reply = reply;
return [{ json: { sessionId, state: JSON.stringify(s), output: reply, booking_created: !!booking, understood: ai, ...(booking || {}) } }];
